#include <vector>
#define main hecbench_original_main
#include "romberg-cuda/main.cu"
#undef main
void emit(int trial,double seconds,const std::vector<double>&result,const std::vector<double>&expected,int repeat,double atol=0.,double rtol=0.){
 double error=0;bool correct=result.size()==expected.size();for(size_t i=0;i<result.size();i++){double e=fabs(result[i]-expected[i]);error=fmax(error,e);correct &= std::isfinite(result[i])&&e<=atol+rtol*fabs(expected[i]);}char path[64];snprintf(path,sizeof(path),"trial_%d.bin",trial);FILE*f=fopen(path,"wb");fwrite(result.data(),8,result.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"timing_region\":\"synchronized_kernel_loop_mean\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,correct?"true":"false",result.size(),error,repeat,path,result.size());if(!correct)exit(1);
}
int main(int argc,char**argv){int nwg=argc>1?atoi(argv[1]):4,repeat=argc>2?atoi(argv[2]):3;std::vector<double>values(nwg),expected(nwg);auto integral=[](double x){return exp(x)*(sin(x)-cos(x))/2.;};for(int i=0;i<nwg;i++)expected[i]=integral(15.*(i+1)/nwg)-integral(15.*i/nwg);double*out;cudaMalloc(&out,nwg*8);romberg<<<nwg,32,17*32*8>>>(0,15,out);cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){auto start=std::chrono::steady_clock::now();for(int j=0;j<repeat;j++)romberg<<<nwg,32,17*32*8>>>(0,15,out);cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeat;cudaMemcpy(values.data(),out,nwg*8,cudaMemcpyDeviceToHost);double sum=0,ref=0;for(int i=0;i<nwg;i++){sum+=values[i];ref+=expected[i];}if(fabs(sum-ref)>EPS)return 2;emit(trial,seconds,values,expected,repeat,1e-7);}cudaFree(out);return 0;}
